// Original LesGo! foundation modules. Fase mapping is a learning guide, not a claim of complete official curriculum coverage.
const VERSION='2026.11.20-grade1-math-full';
const units={};
function unit(id,title,explanation,example,facts,visual='book'){
 units[id]={id,title,explanation,example,visual,facts:facts.map(([question,answer,wrong,why])=>({question,answer:String(answer),wrong:wrong.map(String),explanation:why||explanation}))};
}
// Language and literacy: explicit reading passages, worked examples, and comprehension checks.
unit('huruf','Huruf, bunyi, dan suku kata','Huruf vokal adalah a, i, u, e, dan o. Huruf dapat digabung menjadi suku kata. Gabungan suku kata membentuk kata. Bacalah perlahan sambil menunjuk setiap huruf.','Kata buku terdiri atas bu-ku. Kata mata terdiri atas ma-ta. Ucapkan bunyi b lalu u menjadi bu.',[
 ['Manakah yang termasuk huruf vokal?','a',['b','k','m']],['Kata buku dipisah menjadi …','bu-ku',['b-uku','buk-u','buku-ku']],['Gabungan ma dan ta membentuk kata …','mata',['makan','taman','tamu']],['Ada berapa suku kata pada kata sapi?','2',['1','3','4']]
]);
unit('kalimat','Membaca kalimat sederhana','Kalimat menyampaikan gagasan yang utuh. Awal kalimat menggunakan huruf kapital. Kalimat pernyataan diakhiri tanda titik. Bacalah kalimat, lalu cari siapa yang melakukan kegiatan dan apa kegiatannya.','Bacaan: Siti membawa buku. Ia membaca di teras. Buku Siti berwarna biru. Dari bacaan itu kita tahu Siti membaca buku di teras.',[
 ['Siapa yang membawa buku pada bacaan?','Siti',['Rani','Budi','Ayah']],['Di mana Siti membaca?','Di teras',['Di pasar','Di kebun','Di sungai']],['Kalimat pernyataan diakhiri dengan …','titik',['koma','tanda tanya','tanda petik']],['Penulisan awal kalimat yang benar adalah …','Siti membaca.',['siti membaca.','SITI membaca','siti Membaca']]
]);
unit('tanya','Kata tanya dan informasi','Gunakan siapa untuk menanyakan orang, apa untuk benda atau kegiatan, di mana untuk tempat, kapan untuk waktu, mengapa untuk alasan, dan bagaimana untuk cara. Kalimat tanya diakhiri tanda tanya.','Bacaan: Pada hari Senin, Riko menanam cabai di halaman agar rumahnya lebih hijau. Pertanyaan “Di mana Riko menanam cabai?” dijawab “Di halaman”.',[
 ['Kata tanya untuk tempat adalah …','di mana',['kapan','siapa','mengapa']],['Kapan Riko menanam cabai?','Hari Senin',['Hari Jumat','Pagi Minggu','Bulan Juni']],['Kata tanya untuk alasan adalah …','mengapa',['siapa','kapan','berapa']],['Tanda baca akhir kalimat tanya adalah …','?',['.','!',';']]
]);
unit('cerita','Tokoh, latar, dan urutan cerita','Tokoh adalah pelaku cerita. Latar meliputi tempat dan waktu. Urutan peristiwa membantu kita menceritakan kembali secara runtut. Jangan menambahkan kejadian yang tidak ada dalam bacaan.','Bacaan: Pagi hari, Lala melihat pot bunga jatuh di halaman. Ia memungut tanah yang berserakan. Setelah itu, Lala menanam kembali bunganya dan menyiramnya.',[
 ['Tokoh utama bacaan tersebut adalah …','Lala',['Bunga','Pot','Tanah']],['Latar tempat cerita adalah …','halaman',['kantin','kelas','stasiun']],['Apa yang dilakukan setelah memungut tanah?','Menanam kembali bunga',['Pergi ke pasar','Membeli pot','Menutup pintu']],['Cerita terjadi pada …','pagi hari',['tengah malam','sore hari','waktu yang tidak disebutkan']]
]);
unit('ide','Ide pokok dan kalimat penjelas','Ide pokok adalah gagasan utama paragraf. Kalimat penjelas memberikan contoh, alasan, atau rincian. Untuk menemukan ide pokok, tanyakan: seluruh paragraf ini membahas apa?','Paragraf: Menjaga kebersihan kelas adalah tanggung jawab bersama. Setiap murid membuang sampah pada tempatnya. Petugas piket menyapu lantai. Meja dan kursi juga dirapikan. Ide pokoknya adalah tanggung jawab bersama menjaga kebersihan kelas.',[
 ['Ide pokok paragraf contoh adalah …','Menjaga kebersihan kelas bersama',['Membeli sapu','Mewarnai meja','Ukuran kursi']],['Kalimat penjelas berfungsi untuk …','merinci gagasan utama',['mengganti judul saja','menghapus informasi','membuat paragraf tanpa isi']],['Cara mencari ide pokok adalah menanyakan …','Paragraf membahas apa?',['Berapa hurufnya?','Siapa pencetaknya?','Apa warna kertasnya?']],['Contoh tindakan menjaga kelas adalah …','Merapikan meja',['Membuang sampah di lantai','Mencoret kursi','Menumpuk sampah']]
]);
unit('prosedur','Teks petunjuk dan prosedur','Teks prosedur menjelaskan langkah melakukan sesuatu. Susun langkah secara berurutan, gunakan kata kerja yang jelas, dan sertakan alat atau bahan jika diperlukan. Urutan yang salah dapat membuat hasil berbeda.','Cara menanam kacang hijau: siapkan wadah dan kapas; basahi kapas secukupnya; letakkan biji; simpan di tempat terang; jaga kapas tetap lembap. Jangan merendam biji terus-menerus dalam air.',[
 ['Tujuan teks prosedur adalah …','Menjelaskan langkah kerja',['Menceritakan tokoh fiksi','Menyampaikan rima','Mengurutkan nama orang']],['Langkah sebelum meletakkan biji pada contoh adalah …','Membasahi kapas',['Memanen tanaman','Membuang wadah','Memetik daun']],['Kata yang menunjukkan urutan adalah …','kemudian',['meskipun','tetapi','karena']],['Petunjuk yang baik harus …','jelas dan runtut',['selalu sangat panjang','tanpa kata kerja','acak urutannya']]
]);
unit('deskripsi','Menulis deskripsi berdasarkan pengamatan','Deskripsi menggambarkan objek dengan rincian yang bisa diamati, misalnya warna, bentuk, ukuran, bunyi, atau suasana. Bedakan pengamatan dengan dugaan pribadi.','Contoh: Tas Dina berbentuk persegi panjang. Warnanya hijau dengan dua kantong kecil. Tali tasnya hitam. Kalimat-kalimat ini menjelaskan ciri tas yang terlihat.',[
 ['Teks deskripsi menjelaskan …','ciri objek',['langkah menghitung saja','urutan tahun saja','aturan pertandingan saja']],['Rincian yang dapat diamati adalah …','Tas berwarna hijau',['Tas paling beruntung','Tas tidak pernah sedih','Tas pasti disukai semua orang']],['Bentuk tas pada contoh adalah …','persegi panjang',['lingkaran','segitiga','bola']],['Sebelum menulis deskripsi, sebaiknya …','mengamati objek',['menebak semua ciri','menyalin tanpa membaca','menghilangkan semua rincian']]
]);
unit('fakta','Membedakan fakta dan opini','Fakta dapat diperiksa dengan bukti. Opini merupakan penilaian atau pandangan. Kata terbaik, paling indah, dan menurut saya sering menandai opini, tetapi tetap periksa konteks kalimatnya.','“Perpustakaan buka pukul 08.00” dapat diperiksa melalui jadwal. “Perpustakaan ini paling nyaman di kota” adalah penilaian yang bisa berbeda antarorang.',[
 ['Manakah pernyataan fakta?','Jadwal mencantumkan buka pukul 08.00',['Ini tempat paling indah','Menurutku buku itu membosankan','Warna ini paling bagus']],['Opini adalah …','pandangan atau penilaian',['data yang pasti benar','angka yang selalu terukur','hasil ukur tanpa tafsiran']],['Untuk memeriksa fakta, kita perlu …','bukti yang relevan',['jumlah suka saja','pendapat terkeras','menebak maksud penulis']],['Kata yang sering menandai penilaian adalah …','terbaik',['pukul','tanggal','meter']]
]);
unit('ringkas','Merangkum tanpa mengubah makna','Ringkasan memuat gagasan penting dengan kata-kata sendiri. Baca teks sampai selesai, catat ide utama, hilangkan pengulangan, lalu periksa agar maknanya tetap sesuai. Ringkasan bukan kumpulan kalimat acak.','Teks: Warga membersihkan selokan pada Minggu pagi. Sampah dipilah dan diangkut. Aliran air menjadi lancar. Ringkasan: Warga bekerja bakti membersihkan selokan sehingga air mengalir lancar.',[
 ['Ringkasan harus mempertahankan …','makna pokok teks',['semua pengulangan','semua kata asli','panjang teks semula']],['Langkah pertama merangkum adalah …','membaca teks utuh',['menyalin judul saja','mengubah semua fakta','memilih kalimat acak']],['Informasi penting pada contoh adalah …','Kerja bakti melancarkan aliran air',['Warna mobil warga','Harga sepatu warga','Nama semua warga']],['Ringkasan sebaiknya ditulis dengan …','kata-kata sendiri yang tepat',['informasi rekaan','opini pengganti fakta','huruf awal setiap kalimat saja']]
]);
unit('argumen','Menyusun pendapat dengan alasan','Argumen yang baik menghubungkan pendapat dengan alasan dan bukti. Bukti perlu relevan, dapat diperiksa, dan cukup mendukung kesimpulan. Perbedaan pendapat tidak membenarkan serangan pribadi.','Pendapat: Sekolah perlu menyediakan tempat isi ulang air. Alasan: murid dapat mengurangi botol sekali pakai. Bukti yang perlu dikumpulkan: jumlah botol yang dibuang sebelum dan sesudah fasilitas tersedia.',[
 ['Argumen yang kuat didukung oleh …','alasan dan bukti relevan',['serangan pribadi','huruf kapital saja','pengulangan tanpa bukti']],['Bukti yang relevan untuk contoh adalah …','Jumlah botol yang dibuang',['Warna pagar sekolah','Ukuran lapangan basket','Nama kepala kelas']],['Saat berbeda pendapat, kita sebaiknya …','menanggapi alasan dengan santun',['mengejek pembicara','menyebar data pribadi','memotong semua penjelasan']],['Kesimpulan seharusnya …','sesuai bukti yang tersedia',['selalu lebih luas dari bukti','mengabaikan data','ditentukan popularitas']]
]);
unit('laporan','Laporan pengamatan dan data','Laporan pengamatan mencatat tujuan, cara, hasil, dan simpulan berdasarkan pengamatan. Tuliskan satuan, waktu, dan kondisi agar hasil dapat dipahami. Pisahkan hasil yang terlihat dari dugaan penyebab.','Contoh: Dua pot diamati selama tujuh hari. Pot A mendapat cahaya, pot B berada di tempat gelap. Catat tinggi setiap hari dalam sentimeter. Jangan menyimpulkan hanya dari satu pengukuran.',[
 ['Bagian hasil laporan berisi …','data pengamatan',['cerita khayalan','dugaan tanpa penjelasan','iklan alat']],['Tinggi tanaman dapat dicatat dalam …','sentimeter',['liter','detik','kilogram']],['Pengamatan berulang membantu …','melihat pola perubahan',['menjamin semua dugaan benar','menghapus kebutuhan data','mengganti satuan']],['Simpulan yang baik harus …','sesuai hasil pengamatan',['lebih menarik daripada data','selalu sama dengan dugaan awal','mengabaikan kondisi percobaan']]
]);
unit('kerja','Surat lamaran dan komunikasi kerja','Surat lamaran menjelaskan posisi yang dituju, kualifikasi yang relevan, dan lampiran secara ringkas. Gunakan bahasa sopan serta informasi yang benar. CV dan surat lamaran perlu disesuaikan dengan posisi.','Contoh pembuka: “Saya mengajukan lamaran untuk posisi teknisi jaringan. Saya memiliki pengalaman praktik pemasangan jaringan lokal selama proyek sekolah.” Sertakan pengalaman nyata, bukan kemampuan yang belum dimiliki.',[
 ['Isi lamaran sebaiknya disesuaikan dengan …','posisi yang dituju',['warna logo saja','hobi semua teman','jumlah halaman terbanyak']],['Kualifikasi dalam lamaran harus …','benar dan relevan',['dilebihkan tanpa bukti','sama untuk semua orang','berisi data orang lain']],['Bahasa email kerja sebaiknya …','jelas dan sopan',['penuh ejekan','tanpa tujuan','berisi rahasia orang lain']],['Lampiran yang umum pada lamaran adalah …','CV',['kata sandi email','PIN rekening','kode OTP']]
]);
// English modules include translations and concrete communicative contexts.
unit('greetings','Greetings and introductions','Hello berarti halo. Good morning digunakan pada pagi hari. Untuk mengenalkan diri, gunakan “My name is …”. Untuk menanyakan nama dengan sopan, gunakan “What is your name?”.','Dialog: “Good morning. My name is Rani.” “Good morning, Rani. My name is Dito.” Cobalah menyebut nama sendiri dengan pola yang sama.',[
 ['Sapaan pada pagi hari adalah …','Good morning',['Good night','Goodbye','See you']],['My name is Rani berarti …','Nama saya Rani',['Saya tinggal di Rani','Saya punya buku Rani','Rani sedang tidur']],['Untuk menanyakan nama, gunakan …','What is your name?',['Where is the book?','How many pens?','What color is it?']],['Hello digunakan untuk …','menyapa',['menghitung','meminta harga','menyebut tanggal']]
]);
unit('colors','Colors, numbers, and classroom objects','Red berarti merah, blue berarti biru, green berarti hijau, dan yellow berarti kuning. A book adalah sebuah buku, a pen adalah sebuah pena. One, two, three berarti satu, dua, tiga.','“I have two blue pens” berarti “Saya mempunyai dua pena biru”. Kata two menunjukkan jumlah, blue menunjukkan warna, dan pens menunjukkan benda.',[
 ['Blue berarti …','biru',['merah','hijau','kuning']],['Two menunjukkan jumlah …','dua',['satu','tiga','empat']],['Book berarti …','buku',['meja','pintu','sepatu']],['I have two blue pens menyebut …','dua pena biru',['tiga buku merah','satu meja hijau','dua tas kuning']]
]);
unit('family','Family and daily routines','Mother berarti ibu, father berarti ayah, dan sister berarti saudara perempuan. Untuk kebiasaan, gunakan simple present: “I read every day.” Kata every day berarti setiap hari.','“My father cooks every morning” berarti ayah saya memasak setiap pagi. Pada subjek he, she, atau it, kata kerja simple present umumnya mendapat -s atau -es.',[
 ['Mother berarti …','ibu',['ayah','saudara laki-laki','kakek']],['Every day berarti …','setiap hari',['kemarin','besok','sekali saja']],['Kalimat kebiasaan yang tepat adalah …','She reads every day.',['She read every day yesterday.','She reading every day.','She to read every day.']],['My father cooks menjelaskan kegiatan …','memasak',['berenang','berlari','menggambar']]
]);
unit('places','Places and prepositions','In berarti di dalam, on berarti di atas permukaan, under berarti di bawah, dan next to berarti di samping. Preposition membantu menjelaskan letak benda atau tempat.','“The bag is under the table” berarti tas berada di bawah meja. “The book is on the table” berarti buku berada di atas meja.',[
 ['Under berarti …','di bawah',['di dalam','di samping','di antara']],['The book is on the table berarti buku …','di atas meja',['di bawah meja','di dalam tas','di samping pintu']],['Next to berarti …','di samping',['di bawah','di dalam','jauh dari']],['Kata yang tepat untuk “di dalam kotak” adalah …','in the box',['on the box','under the box','next to the box']]
]);
unit('present','Simple present and present continuous','Simple present menyatakan kebiasaan atau fakta umum. Present continuous menyatakan kegiatan yang sedang berlangsung dengan am/is/are + verb-ing. Penanda waktu membantu memilih bentuk yang sesuai.','Kebiasaan: “They study every evening.” Sedang berlangsung: “They are studying now.” Subjek they memakai are pada present continuous.',[
 ['They are studying now menjelaskan …','kegiatan yang sedang berlangsung',['kebiasaan masa lalu saja','rencana yang dibatalkan','perintah berhenti']],['Bentuk present continuous untuk I adalah …','I am reading.',['I is reading.','I are reading.','I reading.']],['Kalimat kebiasaan adalah …','We study every evening.',['We are studying now.','We studied yesterday.','Study now!']],['He … to school every day.','goes',['go','going','gone']]
]);
unit('past','Talking about past events','Simple past digunakan untuk kejadian yang sudah selesai. Kata kerja beraturan biasanya mendapat -ed; beberapa kata kerja berubah tidak beraturan. Go menjadi went, eat menjadi ate, dan visit menjadi visited.','“Yesterday, we visited a museum. We went there by bus.” Yesterday menunjukkan kemarin. Kedua kegiatan itu telah selesai.',[
 ['Bentuk lampau dari go adalah …','went',['goed','going','goes']],['Yesterday berarti …','kemarin',['besok','sekarang','setiap hari']],['Kalimat lampau yang tepat adalah …','We visited a museum.',['We visit yesterday a museum.','We visiting a museum.','We are visit a museum.']],['Bentuk lampau dari eat adalah …','ate',['eated','eating','eats']]
]);
unit('compare','Comparisons and giving opinions','Comparative membandingkan dua hal. Untuk banyak kata sifat pendek, tambahkan -er: tall menjadi taller. Untuk banyak kata sifat panjang, gunakan more: more interesting. Sertakan alasan saat memberi pendapat.','“A train is longer than a bicycle.” “This book is more interesting than that one.” Than digunakan untuk menyatakan pembanding.',[
 ['Bentuk comparative dari tall adalah …','taller',['tallest','more taller','talling']],['Kata penghubung pembanding adalah …','than',['then','that','this']],['Bentuk yang tepat adalah …','more interesting',['interestinger','most interestinger','interestingest']],['Saat memberi pendapat yang jelas, tambahkan …','alasan yang relevan',['data pribadi teman','ejekan','kata acak']]
]);
unit('instruction','Instructions, safety signs, and manuals','Kalimat instruksi biasanya dimulai dengan kata kerja: open, check, turn off. Larangan menggunakan do not atau don’t. Bacalah petunjuk keselamatan sebelum menggunakan peralatan.','“Turn off the computer before cleaning it” berarti matikan komputer sebelum membersihkannya. “Do not touch” berarti jangan sentuh.',[
 ['Do not touch berarti …','jangan sentuh',['silakan sentuh','buka pintu','nyalakan alat']],['Turn off berarti …','matikan',['nyalakan','perbaiki','beli']],['Sebelum memakai alat, sebaiknya …','membaca petunjuk keselamatan',['mengabaikan semua tanda','mencoba sembarang tombol','melepas semua pelindung']],['Kata kerja untuk “periksa” adalah …','check',['close','carry','write']]
]);
unit('email','Professional email and customer service','Email kerja memuat subject, salam, tujuan, informasi pendukung, dan penutup. Gunakan bahasa sopan. “Could you please …?” adalah cara sopan meminta bantuan.','Subject: Meeting schedule. “Dear Ms. Rina, could you please confirm the meeting time? Thank you.” Pesan ini memiliki tujuan yang jelas: meminta konfirmasi waktu rapat.',[
 ['Subject email berfungsi untuk …','meringkas tujuan pesan',['menyimpan kata sandi','menggantikan semua isi','menulis daftar acak']],['Permintaan yang sopan adalah …','Could you please confirm the time?',['You must answer now!!!','Give me your password.','No greetings needed.']],['Confirm berarti …','mengonfirmasi',['menghapus','menyembunyikan','mengabaikan']],['Penutup email yang sopan adalah …','Thank you.',['Go away.','Whatever.','No reply allowed.']]
]);
// Science, environment, and social studies.
unit('senses','Pancaindra dan pengamatan','Mata membantu melihat, telinga mendengar, hidung mencium, lidah mengecap, dan kulit merasakan sentuhan. Gunakan pengamatan yang aman. Jangan mencicipi bahan yang tidak dikenal untuk melakukan percobaan.','Amati jeruk: warnanya dapat dilihat, aromanya dicium, dan permukaan kulitnya diraba. Rasanya hanya dicoba jika jeruk bersih dan layak dimakan.',[
 ['Indra untuk mendengar adalah …','telinga',['mata','hidung','kulit']],['Permukaan benda dapat dirasakan dengan …','kulit',['telinga','rambut','kuku saja']],['Saat menemukan cairan tidak dikenal, kita harus …','tidak mencicipinya',['mencobanya sedikit','mencampurnya sembarang','menghirupnya dari dekat']],['Warna jeruk diamati menggunakan …','mata',['lidah','telinga','hidung']]
],'nature');
unit('living','Makhluk hidup dan kebutuhannya','Makhluk hidup memerlukan sumber energi dan kondisi yang sesuai untuk hidup. Hewan memerlukan makanan, air, dan udara. Tumbuhan hijau membuat makanan melalui fotosintesis dengan bantuan cahaya.','Tanaman yang dirawat perlu air secukupnya, cahaya yang sesuai, dan tempat tumbuh. Terlalu banyak air juga dapat merusak akar; kebutuhan setiap tanaman berbeda.',[
 ['Contoh makhluk hidup adalah …','pohon mangga',['batu','meja','botol kosong']],['Hewan memperoleh energi terutama dari …','makanan',['warna tubuh','bentuk kandang','nama hewan']],['Tumbuhan hijau membuat makanan melalui …','fotosintesis',['pembekuan','penguapan saja','perkaratan']],['Perawatan tanaman yang tepat adalah …','air sesuai kebutuhan',['selalu merendam akar semua tanaman','menutup semua daun dengan plastik','menaruh semua tanaman di gelap']]
],'nature');
unit('plants','Bagian tumbuhan dan fungsinya','Akar menyerap air dan mineral serta membantu menambatkan tumbuhan. Batang menopang dan mengangkut zat. Daun menjadi tempat utama fotosintesis pada banyak tumbuhan. Bunga berperan dalam perkembangbiakan tumbuhan berbunga.','Pada tanaman cabai, air masuk melalui akar, bergerak melalui batang, dan digunakan pada daun. Buah cabai berkembang setelah proses reproduksi pada bunga.',[
 ['Bagian yang menyerap air adalah …','akar',['bunga','buah','biji kering']],['Tempat utama fotosintesis pada banyak tumbuhan adalah …','daun',['pot','tanah','kelopak saja']],['Batang berfungsi untuk …','menopang dan mengangkut zat',['mengubah semua air menjadi buah','menghasilkan tanah','menggantikan cahaya']],['Bunga berkaitan dengan …','perkembangbiakan',['pembuatan batu','pembentukan awan','penyimpanan listrik']]
],'nature');
unit('matter','Wujud benda dan perubahannya','Benda dapat berwujud padat, cair, atau gas. Mencair adalah perubahan padat menjadi cair, membeku adalah cair menjadi padat, dan menguap adalah cair menjadi gas. Pemanasan atau pendinginan dapat memengaruhi perubahan wujud.','Es dibiarkan di suhu ruang dapat mencair menjadi air. Air yang dimasukkan ke pembeku dapat membeku kembali. Perubahan wujud berbeda dari pembakaran yang menghasilkan zat baru.',[
 ['Es menjadi air disebut …','mencair',['membeku','mengembun','menyublim']],['Air menjadi es disebut …','membeku',['mencair','menguap','mengembun']],['Perubahan cair menjadi gas disebut …','menguap',['membeku','mencair','mengendap']],['Contoh benda berwujud gas adalah …','uap air',['batu','es batu','minyak dalam gelas']]
],'science');
unit('energy','Energi dan perubahan bentuknya','Energi dapat berpindah dan berubah bentuk. Lampu mengubah energi listrik menjadi cahaya dan panas. Energi tidak diciptakan dari ketiadaan; dalam sistem tertutup jumlah energi total tetap.','Pada kipas angin, energi listrik berubah menjadi gerak baling-baling serta sebagian panas dan bunyi. Mematikan kipas yang tidak dipakai mengurangi penggunaan energi listrik.',[
 ['Kipas angin terutama mengubah listrik menjadi …','gerak',['bahan bakar','air','tanah']],['Lampu menghasilkan …','cahaya dan panas',['hanya air','hanya gerak','mineral']],['Contoh penghematan listrik adalah …','mematikan alat yang tidak dipakai',['menyalakan semua lampu siang hari','membuka kulkas terus','membiarkan TV tanpa penonton']],['Energi pada sistem tertutup …','jumlah totalnya tetap',['selalu hilang seluruhnya','tercipta tanpa sumber','tidak dapat berubah bentuk']]
],'science');
unit('forces','Gaya, gerak, dan gesekan','Gaya adalah tarikan atau dorongan yang dapat mengubah gerak atau bentuk benda. Gesekan timbul pada permukaan yang bersentuhan dan menghambat gerak relatifnya. Gesekan juga membantu kita berjalan tanpa mudah tergelincir.','Mendorong troli dapat membuatnya bergerak. Rem sepeda menggunakan gesekan untuk memperlambat putaran roda. Permukaan licin biasanya memberi cengkeraman lebih kecil.',[
 ['Gaya dapat berupa …','tarikan atau dorongan',['warna atau bau','nama atau ukuran','waktu atau tanggal']],['Rem sepeda memanfaatkan …','gesekan',['fotosintesis','penguapan','kondensasi']],['Gesekan membantu kita …','berjalan tanpa mudah tergelincir',['melihat dalam gelap','membuat makanan','mendengar lebih jauh']],['Dorongan dapat mengubah …','gerak benda',['nama benda','jumlah hari','warna langit secara langsung']]
],'science');
unit('water','Siklus air dan penggunaan air','Cahaya matahari membantu air menguap. Uap air mendingin dan mengembun menjadi tetesan yang membentuk awan. Air dapat turun sebagai hujan, lalu mengalir atau meresap ke tanah. Siklus ini berlangsung berulang.','Air hujan dapat meresap melalui tanah yang tidak tertutup rapat. Membiarkan area resapan dan menghemat penggunaan air membantu menjaga ketersediaan air.',[
 ['Perubahan uap menjadi tetesan air disebut …','mengembun',['mencair','membeku','terbakar']],['Sumber energi utama penguapan dalam siklus air adalah …','matahari',['bulan','batu','pasir']],['Air hujan yang masuk ke tanah mengalami …','peresapan',['pembakaran','peleburan logam','fotosintesis']],['Cara menghemat air adalah …','menutup keran setelah dipakai',['membiarkan kebocoran','membuka keran tanpa tujuan','mencuci halaman tanpa batas']]
],'nature');
unit('ecosystem','Rantai makanan dan keseimbangan ekosistem','Ekosistem mencakup makhluk hidup dan lingkungan fisiknya. Produsen seperti tumbuhan membuat makanan, konsumen memakan organisme lain, dan pengurai membantu mengembalikan unsur hara. Perubahan satu populasi dapat memengaruhi bagian lain.','Rantai makanan sederhana: rumput → belalang → katak → ular. Panah menunjukkan aliran energi dari organisme yang dimakan menuju pemakannya. Ini penyederhanaan; di alam banyak rantai saling terhubung.',[
 ['Produsen pada contoh adalah …','rumput',['belalang','katak','ular']],['Panah rantai makanan menunjukkan …','arah aliran energi',['arah angin selalu','urutan ukuran tubuh','umur organisme']],['Pengurai membantu …','mengembalikan unsur hara',['menghasilkan semua cahaya','menghentikan seluruh siklus air','menghapus kebutuhan produsen']],['Gabungan banyak rantai makanan membentuk …','jaring-jaring makanan',['kalender','rangkaian listrik','garis bilangan']]
],'nature');
unit('body','Pernapasan dan pencernaan','Pernapasan mengambil oksigen dan mengeluarkan karbon dioksida. Di paru-paru, pertukaran gas terjadi terutama pada alveolus. Pencernaan memecah makanan agar zat gizinya dapat diserap; sebagian besar penyerapan zat gizi berlangsung di usus halus.','Udara masuk melalui saluran pernapasan menuju paru-paru. Makanan melewati mulut, kerongkongan, lambung, dan usus. Saluran pernapasan dan pencernaan memiliki fungsi berbeda.',[
 ['Pertukaran gas di paru-paru terjadi terutama pada …','alveolus',['lambung','usus besar','kerongkongan']],['Sebagian besar zat gizi diserap di …','usus halus',['hidung','paru-paru','kerongkongan']],['Pernapasan memasok …','oksigen',['pasir','minyak','logam']],['Pencernaan bertujuan membantu …','memecah dan menyerap zat gizi',['membuat udara menjadi batu','mengubah semua makanan menjadi oksigen','menghentikan kebutuhan air']]
],'science');
unit('space','Bumi, Bulan, dan Tata Surya','Bumi berotasi pada porosnya sehingga mengalami pergantian siang dan malam. Bumi juga berevolusi mengelilingi Matahari. Bulan memantulkan cahaya Matahari; Bulan tidak menghasilkan cahaya tampak sendiri seperti bintang.','Saat wilayah tempat kita berada menghadap Matahari, kita mengalami siang. Sekitar satu kali rotasi Bumi memerlukan 24 jam, sedangkan satu revolusi memerlukan sekitar satu tahun.',[
 ['Pergantian siang dan malam disebabkan oleh …','rotasi Bumi',['Bulan berhenti bergerak','Matahari padam','awan menutup seluruh Bumi']],['Bumi mengelilingi …','Matahari',['Mars saja','Bulan','Kutub Utara']],['Cahaya Bulan yang terlihat terutama berasal dari …','pantulan cahaya Matahari',['api di permukaan Bulan','lampu manusia','cahaya laut']],['Satu revolusi Bumi sekitar …','satu tahun',['satu jam','satu hari','satu minggu']]
],'space');
unit('cells','Sel dan organisasi kehidupan','Sel merupakan unit struktural dan fungsional dasar kehidupan. Membran sel mengatur keluar-masuk zat. Inti sel pada sel eukariot menyimpan sebagian besar materi genetik. Sel sejenis dapat membentuk jaringan, lalu organ dan sistem organ.','Urutan organisasi pada manusia: sel otot → jaringan otot → organ jantung → sistem peredaran darah. Sel tumbuhan memiliki dinding sel; banyak sel daun juga memiliki kloroplas.',[
 ['Unit dasar kehidupan adalah …','sel',['planet','batuan','awan']],['Membran sel berperan …','mengatur keluar-masuk zat',['menghasilkan semua cahaya','menggantikan seluruh organ','membuat tanah']],['Urutan yang tepat adalah …','sel–jaringan–organ',['organ–sel–jaringan','jaringan–organ–sel','sel–organ–jaringan']],['Dinding sel merupakan ciri yang ditemukan pada …','sel tumbuhan',['semua sel manusia','sel darah merah manusia','semua virus']]
],'science');
unit('electric','Listrik dan rangkaian sederhana','Arus mengalir pada rangkaian tertutup yang memiliki beda potensial. Dalam model hambatan ohmik, hukum Ohm ditulis V = I × R. Volt untuk tegangan, ampere untuk arus, dan ohm untuk hambatan.','Jika I = 2 A dan R = 3 Ω, maka V = 6 V. Untuk percobaan sekolah gunakan kit baterai bertegangan rendah dengan pendampingan; jangan menggunakan stopkontak rumah.',[
 ['Rumus hukum Ohm adalah …','V = I × R',['V = I + R','R = V × I','I = V × R']],['Satuan arus listrik adalah …','ampere',['meter','liter','kilogram']],['Jika I = 2 A dan R = 3 Ω, tegangannya …','6 V',['5 V','1 V','9 V']],['Rangkaian yang memungkinkan arus mengalir adalah …','rangkaian tertutup',['rangkaian terputus','tanpa sumber tegangan sama sekali','kabel yang dilepas seluruhnya']]
],'science');
unit('atoms','Atom, unsur, senyawa, dan campuran','Unsur tersusun dari satu jenis atom. Senyawa memiliki atom dari unsur berbeda yang berikatan dalam perbandingan tertentu. Campuran terdiri atas beberapa zat yang tidak seluruhnya berikatan menjadi satu senyawa.','Oksigen O₂ adalah unsur, air H₂O adalah senyawa, dan udara adalah campuran berbagai gas. Air garam merupakan campuran yang dapat dipisahkan antara lain melalui penguapan dan pemulihan garam.',[
 ['H₂O merupakan …','senyawa',['unsur tunggal','atom tunggal','batuan']],['Udara merupakan …','campuran gas',['satu unsur saja','satu senyawa murni','logam']],['Unsur tersusun dari …','satu jenis atom',['semua jenis molekul','sel hidup saja','berbagai bahan tanpa aturan']],['Air garam termasuk …','campuran',['unsur logam','atom tunggal','organisme']]
],'science');
unit('reaction','Perubahan fisika dan reaksi kimia','Perubahan fisika tidak mengubah identitas kimia utama zat. Reaksi kimia menghasilkan zat dengan susunan berbeda. Perubahan warna atau gas dapat menjadi petunjuk reaksi, tetapi perlu bukti dan konteks untuk menyimpulkannya.','Es mencair adalah perubahan fisika. Besi berkarat adalah perubahan kimia karena terbentuk senyawa oksida besi. Jangan mencampur bahan pembersih untuk percobaan.',[
 ['Contoh perubahan fisika adalah …','es mencair',['besi berkarat','kayu terbakar','makanan membusuk']],['Perkaratan besi menghasilkan …','zat dengan susunan kimia berbeda',['besi lebih dingin saja','air murni saja','es']],['Gelembung pada air mendidih …','tidak selalu berarti reaksi kimia',['pasti menghasilkan unsur baru','selalu tanda pembusukan','pasti mengandung api']],['Percobaan bahan kimia dilakukan …','dengan petunjuk dan pendampingan',['dengan mencampur pembersih acak','dengan mencicipi zat','tanpa label bahan']]
],'science');
unit('motion','Kecepatan, jarak, dan waktu','Untuk gerak dengan kecepatan tetap, kecepatan = jarak ÷ waktu. Gunakan satuan yang konsisten. Kecepatan rata-rata membandingkan jarak total dengan waktu total perjalanan, termasuk waktu berhenti bila dihitung dalam waktu total.','Sepeda menempuh 12 km dalam 2 jam. Kecepatan rata-ratanya 12 ÷ 2 = 6 km/jam. Jika jarak dinyatakan dalam meter dan waktu dalam sekon, satuan kecepatannya m/s.',[
 ['Rumus kecepatan rata-rata adalah …','jarak total ÷ waktu total',['waktu ÷ jarak','jarak + waktu','jarak × waktu selalu']],['12 km dalam 2 jam berarti …','6 km/jam',['24 km/jam','10 km/jam','14 km/jam']],['Satuan SI kecepatan adalah …','m/s',['kg','liter','m²']],['Sebelum menghitung, satuan perlu …','disesuaikan',['dihapus','selalu diubah menjadi rupiah','dipilih sembarang']]
],'science');
unit('maps','Peta, arah, dan skala','Peta menggambarkan wilayah dengan simbol dan skala. Arah utara pada peta perlu dilihat dari penunjuk arah; tidak semua peta memiliki orientasi sama. Skala 1:100.000 berarti 1 cm pada peta mewakili 100.000 cm atau 1 km di lapangan.','Jika dua tempat berjarak 3 cm pada peta berskala 1:100.000, jarak lurus yang diwakili adalah 3 km. Jarak perjalanan di jalan dapat lebih panjang.',[
 ['Skala 1:100.000 berarti 1 cm mewakili …','1 km',['100 km','10 m','1 m']],['Jarak 3 cm pada skala tersebut mewakili …','3 km',['30 km','300 m','300 km']],['Simbol peta dijelaskan dalam …','legenda',['judul buku lain','daftar harga','tabel perkalian']],['Arah utara ditentukan dari …','penunjuk arah peta',['warna kertas','nama pembaca','ukuran huruf']]
],'map');
unit('needs','Kebutuhan, keinginan, dan prioritas','Kebutuhan adalah sesuatu yang penting bagi kehidupan dan kegiatan dasar. Keinginan merupakan hal yang ingin dimiliki tetapi dapat ditunda. Prioritas membantu menggunakan sumber daya yang terbatas secara bertanggung jawab.','Jika uang saku terbatas dan pensil sekolah sudah habis, membeli pensil dapat didahulukan daripada membeli hiasan tas baru. Keputusan tetap mempertimbangkan keadaan setiap orang.',[
 ['Contoh kebutuhan belajar adalah …','pensil yang diperlukan',['hiasan tas tambahan','mainan terbaru','stiker koleksi']],['Prioritas diperlukan karena sumber daya …','terbatas',['selalu tak terbatas','tidak pernah dipakai','hanya berupa angka']],['Keinginan biasanya dapat …','ditunda sesuai keadaan',['menggantikan semua kebutuhan','selalu dibeli lebih dulu','dipenuhi tanpa sumber daya']],['Keputusan belanja yang baik mempertimbangkan …','kebutuhan dan dana tersedia',['iklan saja','tekanan teman saja','warna kemasan saja']]
],'map');
unit('economy','Produksi, distribusi, dan konsumsi','Produksi menghasilkan atau menambah kegunaan barang dan jasa. Distribusi menyalurkannya kepada pengguna. Konsumsi menggunakan barang atau jasa untuk memenuhi kebutuhan. Satu orang dapat memiliki lebih dari satu peran ekonomi.','Petani menanam beras, pedagang menyalurkannya, keluarga memasaknya untuk dimakan. Dalam contoh sederhana ini terdapat produksi, distribusi, dan konsumsi.',[
 ['Petani menanam padi melakukan …','produksi',['konsumsi akhir','penghapusan data','rotasi']],['Menyalurkan barang disebut …','distribusi',['fotosintesis','rotasi','kondensasi']],['Keluarga memakan nasi melakukan …','konsumsi',['produksi padi','pengiriman hasil panen','ekspor']],['Contoh produksi jasa adalah …','guru memberikan pelajaran',['membuang buku','meminum air','membeli beras untuk dimakan']]
],'map');
unit('history','Kronologi dan sumber sejarah','Kronologi menyusun peristiwa berdasarkan urutan waktu. Sumber sejarah dapat berupa dokumen, benda, foto, atau kesaksian. Periksa asal, waktu pembuatan, dan konteks sumber sebelum menyimpulkan.','Untuk membuat sejarah sekolah, bandingkan akta pendirian, foto lama, arsip kegiatan, dan wawancara. Dua sumber berbeda dapat saling melengkapi atau perlu diperiksa jika bertentangan.',[
 ['Kronologi mengurutkan berdasarkan …','waktu',['warna','ukuran huruf','harga benda']],['Contoh sumber tertulis adalah …','arsip surat',['dugaan tanpa catatan','ramalan','gambar rekaan tanpa konteks']],['Saat sumber bertentangan, sebaiknya …','memeriksa konteks dan sumber lain',['memilih yang paling viral','menghapus semua bukti','langsung menuduh pemilik sumber']],['Sumber sejarah perlu diperiksa …','asal dan konteksnya',['jumlah emoji saja','warna sampul saja','panjang judul saja']]
],'map');
unit('independence','Proklamasi dan makna kemerdekaan','Proklamasi Kemerdekaan Indonesia dibacakan pada 17 Agustus 1945 oleh Soekarno didampingi Mohammad Hatta. Kemerdekaan membuka tanggung jawab bersama membangun kehidupan yang adil, berdaulat, dan menghargai sesama.','Urutan sederhana: persiapan kemerdekaan → pembacaan proklamasi → perjuangan mempertahankan kemerdekaan. Mengisi kemerdekaan di sekolah dapat dilakukan dengan belajar, jujur, dan bekerja sama.',[
 ['Proklamasi Indonesia dibacakan pada …','17 Agustus 1945',['1 Juni 1945','28 Oktober 1928','10 November 1945']],['Pembaca teks proklamasi adalah …','Soekarno',['Ki Hajar Dewantara','Sudirman','Mohammad Yamin']],['Soekarno didampingi oleh …','Mohammad Hatta',['R.A. Kartini','Cut Nyak Dien','Pattimura']],['Contoh tanggung jawab murid adalah …','belajar dan menghargai sesama',['merusak fasilitas','mengejek perbedaan','menyontek tugas']]
],'map');
unit('pancasila','Pancasila dalam kehidupan sehari-hari','Pancasila menjadi dasar negara Indonesia. Nilainya mencakup Ketuhanan, kemanusiaan, persatuan, musyawarah, dan keadilan sosial. Penerapannya tampak dalam tindakan yang menghargai martabat dan hak orang lain.','Saat kerja kelompok, murid mendengarkan pendapat semua anggota, membagi tugas dengan adil, dan tidak mengejek teman yang berbeda latar belakang.',[
 ['Jumlah sila Pancasila adalah …','lima',['tiga','empat','enam']],['Musyawarah berkaitan terutama dengan sila …','keempat',['pertama','kedua','ketiga']],['Menghargai perbedaan dapat dilakukan dengan …','mendengarkan pendapat teman',['memaksa semua sama','mengejek kebiasaan teman','menolak bekerja sama']],['Pembagian tugas yang adil memperhatikan …','kemampuan dan kesepakatan',['siapa yang paling keras','asal daerah saja','pilihan ketua tanpa mendengar anggota']]
],'community');
unit('rules','Aturan, hak, dan tanggung jawab','Aturan membantu kehidupan bersama berjalan tertib. Hak adalah sesuatu yang patut diterima, sedangkan tanggung jawab adalah kewajiban yang perlu dilakukan. Menjalankan tanggung jawab tidak menghapus hak dasar seseorang.','Murid berhak mendapat kesempatan belajar. Murid juga bertanggung jawab menjaga buku pinjaman dan menghargai teman yang sedang berbicara.',[
 ['Contoh tanggung jawab murid adalah …','merawat buku pinjaman',['merusak meja','mengejek teman','menghilangkan alat bersama']],['Aturan bersama membantu …','ketertiban dan keselamatan',['membenarkan perundungan','menghapus semua perbedaan','mengutamakan satu orang saja']],['Saat aturan tidak dipahami, sebaiknya …','bertanya dengan sopan',['langsung melanggar','menyembunyikan kejadian','mengejek pembuat aturan']],['Contoh hak belajar adalah …','kesempatan mengikuti pembelajaran',['memaksa teman memberi jawaban','mengambil buku tanpa izin','mengganggu kelas']]
],'community');
unit('diversity','Keberagaman dan saling menghormati','Indonesia memiliki beragam budaya, bahasa, agama, dan kebiasaan. Menghormati orang lain berarti memperlakukan mereka dengan martabat yang sama. Satu orang tidak mewakili semua anggota kelompok budayanya.','Jika teman memiliki kebiasaan berbeda, tanyakan dengan sopan jika ia bersedia menjelaskan. Jangan menjadikan perbedaan bahasa, fisik, atau keyakinan sebagai bahan ejekan.',[
 ['Sikap terhadap perbedaan yang tepat adalah …','saling menghormati',['memaksa semua seragam','mengucilkan teman','menyebarkan stereotip']],['Sebelum membagikan cerita pribadi teman, sebaiknya …','meminta izin',['langsung mengunggah','mengubah namanya saja','menambahkan gosip']],['Satu orang …','tidak mewakili seluruh kelompok',['selalu mewakili semua kelompoknya','pasti sama dengan semua temannya','boleh direndahkan karena asalnya']],['Jika melihat perundungan, langkah aman adalah …','mencari bantuan orang dewasa tepercaya',['ikut mengejek','merekam untuk mempermalukan','menyalahkan korban']]
],'community');
unit('deliberation','Musyawarah dan penyelesaian konflik','Musyawarah dilakukan dengan menyampaikan alasan, mendengarkan pihak lain, dan mencari keputusan yang dapat diterima bersama. Jika perbedaan belum selesai, gunakan prosedur keputusan yang disepakati tanpa kekerasan.','Kelompok berbeda pendapat tentang tema poster. Setiap anggota menjelaskan usulan dan alasan. Kelompok memilih kriteria bersama: sesuai tugas, dapat dikerjakan, dan bahannya tersedia.',[
 ['Musyawarah dimulai dengan …','mendengar dan menyampaikan alasan',['mengancam anggota','menutup semua usulan','mengabaikan masalah']],['Kriteria bersama membantu keputusan menjadi …','lebih dapat dijelaskan',['selalu menguntungkan ketua','tanpa tanggung jawab','bebas dari semua perbedaan']],['Jika terjadi konflik, kita sebaiknya …','membahas masalah dengan aman',['menyerang pribadi','menyebarkan rahasia','merusak barang']],['Keputusan bersama sebaiknya …','dicatat dan dijalankan bertanggung jawab',['selalu disembunyikan','diubah diam-diam','dilupakan setelah rapat']]
],'community');
unit('constitution','Konstitusi dan lembaga negara','UUD Negara Republik Indonesia Tahun 1945 adalah konstitusi Indonesia. Konstitusi memuat prinsip penyelenggaraan negara serta pengaturan hak dan kewajiban. Lembaga negara memiliki fungsi yang berbeda dan bekerja sesuai ketentuan hukum.','Presiden memimpin pemerintahan. DPR memiliki fungsi legislasi, anggaran, dan pengawasan. Pelajari fungsi lembaga, bukan sekadar menghafal nama pejabat yang dapat berganti.',[
 ['Konstitusi Indonesia adalah …','UUD NRI Tahun 1945',['kamus bahasa','jadwal kelas','buku harian']],['Salah satu fungsi DPR adalah …','pengawasan',['mengadili semua perkara','mencetak semua uang sendiri','menggantikan seluruh pengadilan']],['Presiden memimpin …','pemerintahan',['semua pengadilan secara pribadi','setiap organisasi siswa','semua partai sekaligus']],['Nama pejabat …','dapat berubah sehingga perlu diperiksa',['selalu tetap selamanya','menggantikan isi konstitusi','tidak pernah relevan']]
],'community');
unit('integrity','Kejujuran dan tanggung jawab pribadi','Jujur berarti menyampaikan sesuatu sesuai kenyataan dan tidak mengambil hasil orang lain sebagai milik sendiri. Jika melakukan kesalahan, akui dengan aman, perbaiki, dan belajar dari kejadian itu.','Saat kesulitan menjawab tugas, tuliskan usaha sendiri dan tanyakan bagian yang belum dipahami. Mengakui belum paham memberi kesempatan untuk belajar lebih baik.',[
 ['Contoh jujur saat belajar adalah …','mengakui bagian yang belum dipahami',['menyalin lalu mengaku karya sendiri','mengubah nilai diam-diam','mengambil jawaban teman']],['Setelah membuat kesalahan, langkah baik adalah …','memperbaikinya dan belajar',['menyalahkan orang lain','menghapus bukti untuk menipu','mengulangi tanpa memeriksa']],['Karya orang lain yang dipakai perlu …','diakui sumbernya',['diklaim sepenuhnya milik sendiri','diubah namanya saja','disembunyikan asalnya']],['Belajar dari kesalahan membantu …','memperbaiki pemahaman',['menjamin tidak perlu latihan','menghindari semua tanggung jawab','menghapus kebutuhan umpan balik']]
],'community');
unit('care','Empati, menolong, dan batas pribadi','Empati adalah usaha memahami perasaan dan kebutuhan orang lain. Menolong perlu memperhatikan keselamatan, persetujuan, dan kemampuan kita. Kamu juga boleh meminta bantuan dan menjaga batas pribadi.','Teman terlihat sedih. Kamu dapat bertanya apakah ia ingin bercerita, mendengarkan tanpa mengejek, dan mengajak orang dewasa tepercaya jika situasinya membutuhkan bantuan.',[
 ['Empati berarti berusaha …','memahami perasaan orang lain',['mengendalikan semua keputusan teman','menyebarkan rahasianya','memaksanya bercerita']],['Sebelum memberi bantuan fisik, sebaiknya …','meminta izin bila memungkinkan',['langsung memaksa','mengabaikan penolakan','merekam tanpa izin']],['Jika masalah melebihi kemampuan kita, sebaiknya …','meminta bantuan orang tepercaya',['menanggung semuanya sendiri','menjanjikan hal yang tidak mampu','menutup semua komunikasi']],['Batas pribadi orang lain perlu …','dihormati',['diabaikan demi bercanda','diumumkan tanpa izin','dipaksa berubah']]
],'community');
unit('reflection','Refleksi diri dan menghargai keyakinan','Refleksi membantu kita memeriksa tindakan, niat, dan akibatnya. Setiap murid dapat mendalami ajaran agamanya dengan guru atau pendamping yang sesuai. Dalam ruang bersama, hormati kegiatan ibadah dan kebebasan keyakinan orang lain.','Setelah kerja kelompok, tanyakan: apakah saya sudah jujur, membantu, dan menghargai teman? Pilih satu tindakan yang ingin diperbaiki besok. Modul ini membahas budi pekerti bersama, bukan tata ibadah agama tertentu.',[
 ['Refleksi diri membantu kita …','menilai dan memperbaiki tindakan',['menghakimi keyakinan teman','memastikan diri selalu benar','menghindari tanggung jawab']],['Belajar tata ibadah agama tertentu sebaiknya bersama …','guru atau pendamping yang sesuai',['sumber acak tanpa diperiksa','orang yang mengejek agama','tebakan dari media sosial']],['Terhadap ibadah orang lain, kita perlu …','menghormati',['mengganggu','mengejek','memaksa berhenti']],['Hasil refleksi sebaiknya diikuti …','rencana perbaikan yang nyata',['ejekan terhadap diri sendiri','janji tanpa langkah','menyalahkan semua orang']]
],'community');
unit('hygiene','Kebersihan dan kebiasaan sehat','Menjaga kebersihan membantu mengurangi perpindahan kotoran dan kuman. Cuci tangan dengan sabun dan air mengalir, terutama sebelum makan dan setelah dari toilet. Istirahat, makanan beragam, dan aktivitas fisik mendukung kebugaran.','Saat tangan kotor setelah bermain, basahi, gunakan sabun, gosok seluruh bagian tangan, bilas, dan keringkan. Minta bantuan orang dewasa jika ada kebutuhan kesehatan khusus.',[
 ['Sebelum makan sebaiknya …','mencuci tangan dengan sabun',['mengusap tangan ke baju saja','mengabaikan tangan kotor','berbagi botol tanpa izin']],['Kebugaran didukung oleh …','istirahat dan aktivitas yang sesuai',['begadang terus','tidak pernah bergerak','melewatkan semua waktu makan']],['Kotoran di sela jari perlu …','dibersihkan saat mencuci tangan',['dibiarkan','ditutup tinta','diusap ke meja']],['Jika alat makan jatuh ke tempat kotor, sebaiknya …','dibersihkan sebelum digunakan',['langsung dipakai','disembunyikan','dipinjamkan tanpa dicuci']]
],'sport');
unit('movement','Gerak dasar dan koordinasi','Gerak lokomotor memindahkan tubuh, seperti berjalan dan melompat. Gerak nonlokomotor dilakukan tanpa berpindah tempat secara keseluruhan, seperti menekuk. Gerak manipulatif melibatkan benda, seperti melempar bola.','Di area aman, lakukan jalan di tempat lalu berjalan ke depan. Amati perbedaan gerak. Sesuaikan aktivitas dengan kemampuan tubuh dan arahan guru; berhenti jika merasa sakit atau pusing.',[
 ['Contoh gerak lokomotor adalah …','berjalan ke depan',['menekuk siku sambil diam','memutar pergelangan','mengangguk']],['Melempar bola termasuk gerak …','manipulatif',['hanya nonlokomotor','perubahan wujud','rotasi Bumi']],['Sebelum aktivitas, area perlu …','aman dan cukup ruang',['licin dan penuh benda','gelap tanpa pengawasan','dekat jalan ramai']],['Jika merasa sakit saat bergerak, sebaiknya …','berhenti dan memberi tahu pendamping',['memaksa terus','menutupi keluhan','menambah beban']]
],'sport');
unit('fairplay','Permainan, aturan, dan sportivitas','Sportivitas berarti mengikuti aturan, menghormati lawan, dan menerima hasil tanpa kekerasan. Tujuan permainan sekolah juga mencakup kerja sama dan kesempatan ikut serta sesuai kemampuan, bukan menang saja.','Sebelum bermain, sepakati batas lapangan dan aturan giliran. Jika bola keluar, ikuti aturan yang disepakati. Beri dukungan pada teman yang sedang belajar.',[
 ['Contoh sportivitas adalah …','menghormati lawan dan aturan',['mengejek yang kalah','mengubah skor diam-diam','mendorong lawan sengaja']],['Aturan permainan sebaiknya disepakati …','sebelum bermain',['hanya setelah kalah','diam-diam oleh satu orang','setelah semua pulang']],['Teman yang sedang belajar sebaiknya …','didukung dan diberi kesempatan',['selalu dikeluarkan','ditertawakan','diabaikan']],['Saat hasil tidak sesuai harapan, kita dapat …','mengevaluasi dan mencoba lagi',['merusak alat','menyerang lawan','memalsukan skor']]
],'sport');
unit('fitness','Kebugaran dan latihan bertahap','Latihan perlu bertahap, sesuai kemampuan, dan disertai waktu pemulihan. Pemanasan menyiapkan tubuh sebelum aktivitas, sedangkan pendinginan membantu beralih ke aktivitas yang lebih ringan. Kebutuhan tiap orang berbeda.','Contoh rencana ringan: mulai dengan jalan santai, lanjutkan kegiatan sesuai arahan guru, lalu turunkan intensitas secara bertahap. Minum sesuai kebutuhan dan cuaca; jangan membandingkan kemampuan tubuh secara mengejek.',[
 ['Latihan sebaiknya ditingkatkan secara …','bertahap',['mendadak tanpa batas','berdasarkan ejekan teman','tanpa istirahat']],['Pemanasan dilakukan …','sebelum aktivitas utama',['hanya saat tidur','sebagai pengganti seluruh pemulihan','setelah semua selesai saja']],['Pemulihan penting untuk …','memberi tubuh waktu beristirahat',['membuat latihan selalu lebih berat','menghapus kebutuhan tidur','menghindari semua gerak selamanya']],['Kemampuan setiap orang …','dapat berbeda',['pasti sama','ditentukan nilai satu tes saja','boleh dijadikan ejekan']]
],'sport');
unit('colorart','Warna, garis, dan bentuk dalam gambar','Garis, bentuk, warna, tekstur, dan ruang adalah unsur rupa. Garis dapat lurus, lengkung, tebal, atau tipis. Warna dan bentuk dapat membantu menyampaikan suasana tanpa harus membuat semua gambar sama.','Gambar taman dapat memakai garis lengkung untuk jalur dan bentuk lingkaran untuk bunga. Jelaskan pilihanmu: mengapa memakai warna atau bentuk tertentu?',[
 ['Garis dan warna termasuk …','unsur rupa',['satuan massa','jenis energi','organ tubuh']],['Contoh garis lengkung adalah …','garis membentuk busur',['garis lurus mendatar','titik tunggal','angka tanpa bentuk']],['Pilihan warna dalam karya dapat menyampaikan …','suasana',['berat benda sebenarnya','waktu pasti pembuatan','harga yang selalu sama']],['Karya teman sebaiknya dibahas dengan …','tanggapan yang menghargai',['ejekan','merusak hasilnya','memaksa semua serupa']]
],'art');
unit('rhythm','Irama, ketukan, dan pola bunyi','Ketukan membantu menjaga keteraturan waktu dalam musik. Irama adalah pola panjang-pendek dan penekanan bunyi. Tempo menunjukkan cepat-lambatnya lagu. Dinamika menunjukkan kuat-lemahnya bunyi.','Tepuk pola: tepuk–diam–tepuk–tepuk. Ulangi dengan tempo lambat, lalu sedang. Polanya tetap, tetapi kecepatannya berubah. Jaga volume agar nyaman bagi orang sekitar.',[
 ['Tempo menunjukkan …','cepat-lambatnya musik',['tinggi badan pemain','warna alat','jumlah penonton']],['Dinamika berkaitan dengan …','kuat-lemahnya bunyi',['letak bangku','bahan pakaian','warna nada tertulis']],['Pola tepuk dapat membantu melatih …','irama',['perubahan kimia','gravitasi','skala peta']],['Saat berlatih bunyi, volume sebaiknya …','nyaman dan aman',['selalu paling keras','ditingkatkan tanpa batas','mengganggu orang sekitar']]
],'art');
unit('design','Komposisi, poster, dan komunikasi visual','Komposisi mengatur unsur visual agar pesan mudah dipahami. Gunakan hierarki: informasi terpenting paling menonjol. Perhatikan kontras, keterbacaan, jarak, dan hak penggunaan gambar.','Poster ajakan membaca dapat memiliki judul besar, satu ilustrasi utama, lalu waktu dan tempat kegiatan. Uji dengan meminta teman menyebut informasi yang terlihat pertama.',[
 ['Hierarki visual membantu …','menentukan urutan perhatian',['menyembunyikan semua informasi','menghapus judul','memenuhi semua ruang']],['Poster mudah dibaca jika …','kontras dan ukuran huruf sesuai',['teks sangat kecil','semua elemen bertumpuk','warna teks sama dengan latar']],['Sebelum memakai gambar orang lain, periksa …','izin atau lisensinya',['jumlah emoji','harga komputer','warna ruangan']],['Uji poster dapat dilakukan dengan …','meminta pembaca menemukan pesan utama',['menutup semua teks','menghapus informasi acara','mengganti semua huruf acak']]
],'art');
unit('craft','Berkarya, dokumentasi, dan apresiasi','Proses berkarya meliputi mencari ide, membuat rancangan, mencoba, memperbaiki, dan mendokumentasikan hasil. Apresiasi menjelaskan apa yang diamati dan alasan penilaiannya tanpa merendahkan pembuat karya.','Buat rancangan tempat pensil dari bahan bekas yang bersih. Periksa keamanan tepi bahan bersama pendamping. Foto proses dan tuliskan satu hal yang berhasil serta satu hal yang ingin diperbaiki.',[
 ['Rancangan dibuat untuk …','merencanakan bentuk dan langkah',['menghindari semua percobaan','meniru tanpa berpikir','mengganti kebutuhan alat']],['Dokumentasi proses membantu …','melihat perkembangan karya',['menghapus ide awal','membuat semua karya sama','menghilangkan umpan balik']],['Tanggapan yang membangun adalah …','Tulisan judul bisa diperbesar agar terbaca.',['Karyamu jelek sekali.','Semua karya harus sama.','Jangan mencoba lagi.']],['Bahan bekas untuk karya harus …','bersih dan aman',['selalu tajam','tidak perlu diperiksa','berasal dari bahan berbahaya']]
],'art');
unit('digital','Perangkat digital dan keamanan akun','Perangkat keras adalah bagian fisik komputer. Perangkat lunak adalah program yang menjalankan tugas. Gunakan kata sandi yang kuat dan unik, jangan bagikan OTP, dan periksa alamat situs sebelum masuk.','Keyboard adalah perangkat keras, sedangkan aplikasi pengolah kata adalah perangkat lunak. Jika pesan meminta OTP untuk menerima hadiah, jangan berikan dan minta pendamping memeriksa.',[
 ['Keyboard termasuk …','perangkat keras',['perangkat lunak','data awan','kata sandi']],['OTP sebaiknya …','dirahasiakan',['dikirim ke siapa saja','diunggah ke grup','dipakai sebagai nama akun']],['Aplikasi pengolah kata termasuk …','perangkat lunak',['kabel','monitor','printer']],['Sebelum memasukkan kata sandi, periksa …','alamat situs dan konteksnya',['jumlah gambar saja','warna tombol saja','jumlah iklan']]
],'code');
unit('algorithm','Algoritma dan berpikir terstruktur','Algoritma adalah urutan langkah yang jelas untuk menyelesaikan masalah. Dekomposisi memecah masalah menjadi bagian kecil. Uji algoritma dengan contoh biasa serta kasus batas agar kesalahannya terlihat.','Algoritma mencari bilangan terbesar dari dua bilangan: baca a dan b; jika a lebih besar dari b, pilih a; jika tidak, pilih b. Untuk a = b, keduanya memiliki nilai terbesar yang sama.',[
 ['Algoritma adalah …','urutan langkah penyelesaian',['nama perangkat','warna layar','satu tebakan']],['Dekomposisi berarti …','memecah masalah menjadi bagian kecil',['menghapus masalah','menyalin semua jawaban','memperbesar tanpa alasan']],['Jika a = 4 dan b = 7, nilai terbesar …','7',['4','3','11']],['Kasus batas perlu diuji untuk …','menemukan kesalahan yang terlewat',['menghindari semua pengujian','menghapus data','membenarkan dugaan tanpa bukti']]
],'code');
unit('data','Data, tabel, dan visualisasi','Data adalah catatan hasil pengamatan atau pengukuran. Tabel membantu menyusun data. Diagram batang cocok untuk membandingkan kategori, sedangkan grafik garis sering digunakan untuk perubahan sepanjang waktu. Pilih skala yang tidak menyesatkan.','Data buku yang dibaca: Senin 3, Selasa 5, Rabu 4. Totalnya 12 buku. Untuk menjelaskan perubahan harian, grafik garis dapat digunakan; beri label hari dan jumlah buku.',[
 ['Total 3, 5, dan 4 adalah …','12',['9','11','15']],['Diagram batang cocok untuk …','membandingkan kategori',['menyimpan kata sandi','memutar video','mengganti pengukuran']],['Grafik perlu memiliki …','label dan skala yang jelas',['skala yang disembunyikan','judul menyesatkan','angka tanpa satuan selamanya']],['Data pengamatan sebaiknya …','dicatat apa adanya',['diubah agar selalu sesuai dugaan','dipilih yang bagus saja','dihilangkan jika berbeda']]
],'code');
unit('spreadsheet','Rumus dasar lembar kerja','Lembar kerja menyusun data dalam sel, baris, dan kolom. Alamat A1 menunjukkan kolom A baris 1. Rumus umumnya dimulai dengan =. SUM menjumlahkan rentang; AVERAGE menghitung rata-rata numerik.','Jika A1 = 10 dan A2 = 20, =SUM(A1:A2) menghasilkan 30. =AVERAGE(A1:A2) menghasilkan 15. Periksa rentang agar tidak ada data yang terlewat.',[
 ['Alamat A1 berarti …','kolom A baris 1',['baris A kolom 1','halaman A nomor 1','nama file']],['Rumus penjumlahan rentang adalah …','=SUM(A1:A2)',['SUM tanpa alamat','A1:A2 saja','=COLOR(A1:A2)']],['Rata-rata 10 dan 20 adalah …','15',['30','10','20']],['Rumus biasanya dimulai dengan …','=',['#','?','!']]
],'code');
unit('network','Jaringan komputer dan internet','Jaringan menghubungkan perangkat untuk bertukar data. LAN mencakup area lokal. Router meneruskan paket antaring jaringan, sedangkan switch menghubungkan perangkat dalam jaringan lokal. Internet merupakan jaringan dari banyak jaringan.','Komputer laboratorium dapat terhubung ke switch, lalu router menghubungkan LAN ke jaringan lain. Gangguan bisa terjadi pada perangkat, kabel, konfigurasi, atau penyedia layanan.',[
 ['LAN adalah jaringan …','area lokal',['khusus seluruh galaksi','tanpa perangkat','yang selalu nirkabel']],['Router terutama berfungsi …','meneruskan paket antaring jaringan',['mencetak dokumen','menyimpan semua kata sandi','mengisi daya semua perangkat']],['Switch digunakan untuk …','menghubungkan perangkat pada LAN',['mengukur suhu','mengganti semua aplikasi','membuat tinta']],['Internet adalah …','jaringan dari banyak jaringan',['satu komputer saja','satu kabel milik murid','nama browser']]
],'code');
unit('programming','Variabel, kondisi, dan perulangan','Variabel menyimpan nilai. Kondisi memilih langkah berdasarkan pengujian. Perulangan menjalankan langkah berulang. Program perlu memvalidasi masukan dan diuji dengan berbagai nilai, bukan hanya satu contoh.','Pseudocode: jika nilai >= 75, tampilkan “Tuntas”; jika tidak, tampilkan “Latihan lagi”. Angka 75 di sini hanya contoh batas latihan, bukan standar kelulusan semua sekolah.',[
 ['Variabel digunakan untuk …','menyimpan nilai',['menghapus semua data','mengganti layar','menghubungkan listrik']],['Struktur if digunakan untuk …','percabangan kondisi',['membuat kabel','mengisi baterai','mencetak tanpa syarat']],['Perulangan membantu …','menjalankan langkah berulang',['menghindari semua perintah','membuat semua nilai sama','menghapus pengujian']],['Pada contoh, nilai 80 menghasilkan …','Tuntas',['Latihan lagi','Error pasti','Tidak ada keluaran']]
],'code');
unit('html','HTML, CSS, dan halaman web','HTML menyusun struktur konten. CSS mengatur tampilan. JavaScript dapat menambahkan interaksi. Gunakan elemen semantik, teks alternatif gambar, dan label formulir agar halaman lebih mudah diakses.','Judul halaman dapat menggunakan elemen h1, paragraf menggunakan p, dan tautan menggunakan a. Sebuah tombol tindakan sebaiknya memakai button, bukan gambar tanpa label.',[
 ['HTML terutama mengatur …','struktur konten',['tegangan listrik','alamat rumah pengguna','kecepatan kipas']],['CSS terutama mengatur …','tampilan',['isi basis data otomatis','pembayaran bank','izin administrator']],['Teks alternatif gambar membantu …','aksesibilitas',['mengganti semua isi halaman','menyimpan kata sandi','menghapus label']],['Elemen tindakan yang tepat adalah …','button',['gambar tanpa label','paragraf tanpa interaksi','spasi kosong']]
],'code');
unit('database','Basis data dan query dasar','Basis data menyimpan data secara terstruktur. Tabel relasional terdiri atas baris dan kolom. Primary key mengidentifikasi baris secara unik. Query perlu menggunakan parameter agar masukan pengguna tidak menjadi kode SQL.','Tabel murid memiliki id, nama, dan kelas. SELECT nama FROM murid mengambil kolom nama. Akses data pribadi tetap harus diperiksa di server, bukan hanya disembunyikan di layar.',[
 ['Primary key berfungsi untuk …','mengidentifikasi baris secara unik',['memberi warna tabel','menghapus semua kolom','mengganti kata sandi']],['SELECT digunakan untuk …','mengambil data',['memanaskan prosesor','mengubah tegangan','mengganti kabel']],['Query berparameter membantu mencegah …','injeksi SQL',['listrik mati','layar pecah','kehabisan tinta']],['Izin membaca data diperiksa …','di server',['hanya lewat warna tombol','hanya di catatan pengguna','tidak perlu diperiksa']]
],'code');
unit('testing','Pengujian, debugging, dan versi kode','Pengujian memeriksa perilaku program terhadap hasil yang diharapkan. Debugging mencari dan memperbaiki penyebab kesalahan. Version control mencatat perubahan agar dapat ditinjau dan dipulihkan. Jangan memasukkan kredensial ke repositori.','Untuk fungsi penjumlahan, uji bilangan positif, nol, negatif, dan masukan tidak valid sesuai spesifikasi. Catat langkah reproduksi ketika melaporkan bug.',[
 ['Debugging bertujuan …','mencari dan memperbaiki kesalahan',['menghapus semua pengujian','mengganti nama bug saja','mengabaikan laporan']],['Version control mencatat …','riwayat perubahan',['hanya warna layar','semua PIN pengguna','suhu ruangan']],['Laporan bug sebaiknya memuat …','langkah reproduksi dan hasil',['ejekan pembuat kode','kata “rusak” saja','kata sandi admin']],['Kredensial dalam kode sebaiknya …','dikelola sebagai rahasia terpisah',['diunggah publik','ditaruh di komentar publik','dikirim ke semua murid']]
],'code');
unit('ip','Alamat IP, subnet, dan layanan jaringan','Alamat IP mengidentifikasi antarmuka pada jaringan IP. Subnet membagi ruang alamat secara logis. DNS menerjemahkan nama domain menjadi informasi alamat, dan DHCP dapat memberikan konfigurasi jaringan secara otomatis.','Perangkat dapat memperoleh alamat lokal dari DHCP. Ketika membuka situs, DNS membantu menemukan alamat tujuan. Alamat IP privat tidak otomatis dapat diakses langsung dari internet.',[
 ['DNS membantu menerjemahkan …','nama domain menjadi informasi alamat',['gambar menjadi kertas','suhu menjadi waktu','PIN menjadi kata sandi']],['DHCP dapat memberikan …','konfigurasi jaringan otomatis',['baterai baru','semua lisensi perangkat lunak','izin melihat semua data']],['Subnet digunakan untuk …','membagi ruang alamat jaringan',['mengganti keyboard','menghapus browser','mengisi tinta']],['Alamat IP privat …','tidak otomatis dapat diakses langsung dari internet',['selalu publik','selalu sama untuk semua perangkat','merupakan kata sandi']]
],'code');
unit('troubleshooting','Troubleshooting jaringan secara sistematis','Mulai dari gejala dan ruang lingkup masalah. Periksa koneksi fisik, alamat IP, gateway, DNS, lalu layanan tujuan sesuai kebutuhan. Ubah satu hal dalam satu waktu dan catat hasil. Jangan mengubah jaringan yang bukan wewenangmu.','Jika satu komputer tidak tersambung tetapi komputer lain bisa, periksa perangkat lokal terlebih dahulu. Jika semua perangkat gagal, periksa jalur bersama atau eskalasikan ke penanggung jawab.',[
 ['Langkah awal troubleshooting adalah …','mengenali gejala dan ruang lingkup',['mengganti semua alat','mereset semua kata sandi','menyalahkan pengguna']],['Perubahan sebaiknya dilakukan …','satu per satu dan dicatat',['semuanya sekaligus tanpa catatan','diam-diam pada jaringan orang','tanpa tujuan']],['Jika hanya satu perangkat gagal, periksa …','perangkat dan koneksi lokalnya',['semua satelit','semua website dunia','warna meja']],['Jaringan di luar wewenang sebaiknya …','dilaporkan ke penanggung jawab',['diubah tanpa izin','dipindai sembarang','dihapus konfigurasinya']]
],'code');
unit('security','Keamanan jaringan dan cadangan','Prinsip hak akses minimum memberikan izin sesuai tugas saja. Pembaruan perangkat lunak memperbaiki kelemahan yang diketahui. Cadangan perlu dipisahkan dari data utama dan diuji pemulihannya. Keamanan tidak cukup hanya dengan satu alat.','Akun murid tidak memerlukan izin administrator server. Cadangan yang belum pernah diuji belum memberikan bukti bahwa pemulihan benar-benar berhasil.',[
 ['Hak akses minimum berarti …','izin sesuai kebutuhan tugas',['semua akun menjadi admin','tanpa kata sandi','semua data dibuat publik']],['Cadangan perlu …','diuji pemulihannya',['hanya diberi nama backup','selalu disimpan di lokasi sama saja','dihapus setelah dibuat']],['Pembaruan perangkat lunak dapat …','memperbaiki kelemahan yang diketahui',['menjamin tak pernah ada risiko','mengganti semua data','menghapus kebutuhan izin']],['Akun murid sebaiknya …','memiliki izin yang sesuai',['otomatis admin server','bisa melihat semua data pribadi','memiliki akses tanpa batas']]
],'code');
unit('accounting','Persamaan dasar akuntansi','Persamaan dasar akuntansi adalah aset = liabilitas + ekuitas. Aset adalah sumber daya yang dikendalikan entitas; liabilitas merupakan kewajiban, dan ekuitas adalah hak residual setelah liabilitas dikurangkan. Setiap transaksi perlu bukti yang sesuai.','Pemilik menyetor kas Rp1.000.000 sebagai modal. Aset kas bertambah Rp1.000.000 dan ekuitas bertambah Rp1.000.000. Persamaan tetap seimbang.',[
 ['Persamaan dasar akuntansi adalah …','Aset = Liabilitas + Ekuitas',['Aset = Pendapatan − Kas','Ekuitas = Aset + Liabilitas','Kas = Semua Beban']],['Setoran modal pemilik menambah …','kas dan ekuitas',['utang dan beban','beban dan persediaan berkurang','pendapatan penjualan otomatis']],['Liabilitas berarti …','kewajiban',['seluruh aset','semua kas','laba bersih']],['Transaksi perlu didukung …','bukti yang sesuai',['perkiraan tanpa catatan','cerita tanpa tanggal','jumlah suka']]
],'business');
unit('journal','Debit, kredit, dan jurnal umum','Debit dan kredit adalah sisi pencatatan, bukan sinonim untung dan rugi. Pada pencatatan dasar, kenaikan aset dan beban umumnya di debit; kenaikan liabilitas, ekuitas, dan pendapatan umumnya di kredit. Total debit harus sama dengan total kredit.','Membeli perlengkapan tunai Rp100.000: debit perlengkapan Rp100.000, kredit kas Rp100.000. Nilai aset berpindah dari kas ke perlengkapan.',[
 ['Total debit dan kredit jurnal harus …','sama',['selalu debit lebih besar','selalu kredit nol','berbeda agar untung']],['Kenaikan aset umumnya dicatat di …','debit',['kredit selalu','catatan tanpa nilai','luar jurnal']],['Pembelian perlengkapan tunai mengurangi …','kas',['modal secara otomatis','semua pendapatan','seluruh utang']],['Debit tidak selalu berarti …','kerugian',['sisi pencatatan','bagian jurnal','nilai transaksi']]
],'business');
unit('statements','Laporan laba rugi dan posisi keuangan','Laporan laba rugi menunjukkan pendapatan dan beban selama suatu periode. Laporan posisi keuangan menunjukkan aset, liabilitas, dan ekuitas pada tanggal tertentu. Arus kas berbeda dari laba karena waktu penerimaan dan pembayaran dapat berbeda.','Pendapatan Rp500.000 dan beban Rp300.000 menghasilkan laba Rp200.000 dalam contoh sederhana. Jika penjualan belum dibayar pelanggan, laba tersebut tidak otomatis sama dengan kas yang diterima.',[
 ['Laba sederhana dihitung dari …','pendapatan dikurangi beban',['aset ditambah semua utang','kas dikali penjualan','beban dikurangi pendapatan selalu']],['Pendapatan 500.000 dan beban 300.000 menghasilkan …','laba 200.000',['laba 800.000','rugi 200.000','kas pasti 500.000']],['Laporan posisi keuangan menunjukkan keadaan …','pada tanggal tertentu',['hanya hari libur','selalu tanpa tanggal','untuk satu transaksi saja']],['Laba dan arus kas …','dapat berbeda',['selalu sama persis','tidak pernah berhubungan','keduanya bukan data keuangan']]
],'business');
unit('business','Usaha, harga pokok, dan nilai pelanggan','Usaha menyediakan nilai bagi pelanggan dengan sumber daya yang tersedia. Biaya bahan, tenaga, dan biaya lain perlu dihitung. Harga jual tidak sama dengan laba; laba dipengaruhi semua biaya yang relevan serta jumlah penjualan.','Jika satu produk memerlukan bahan Rp3.000 dan biaya kemasan Rp1.000, biaya yang tercatat baru Rp4.000. Periksa biaya tenaga, platform, dan operasional sebelum menyimpulkan laba.',[
 ['Harga jual dikurangi seluruh biaya terkait membantu menghitung …','laba',['jumlah huruf produk','berat kemasan','lama sekolah']],['Bahan 3.000 dan kemasan 1.000 berjumlah …','4.000',['2.000','3.000','5.000']],['Sebelum menjual produk, pahami …','kebutuhan pelanggan',['keinginan penjual saja','warna meja pelanggan','semua data pribadi pelanggan']],['Biaya tenaga dan operasional …','perlu diperhitungkan bila relevan',['selalu boleh diabaikan','pasti nol','sama dengan omzet']]
],'business');
unit('project','Merancang proyek dan portofolio','Proyek dimulai dari masalah, tujuan, kriteria keberhasilan, rencana, pelaksanaan, pengujian, dan refleksi. Portofolio menampilkan proses serta kontribusi yang nyata. Cantumkan peran anggota dan sumber yang digunakan.','Contoh proyek RPL: aplikasi daftar buku. Kriteria: pengguna bisa menambah, mencari, dan menghapus buku miliknya. Uji setiap fungsi, catat hasil, dan jelaskan keterbatasannya.',[
 ['Kriteria keberhasilan perlu dibuat …','sebelum menilai hasil proyek',['setelah mengubah semua data','tanpa tujuan','hanya jika proyek gagal']],['Portofolio sebaiknya menunjukkan …','proses dan kontribusi nyata',['karya orang lain sebagai milik sendiri','rahasia pengguna','nilai rekaan']],['Setelah pengujian, tim sebaiknya …','memperbaiki dan merefleksikan hasil',['menyembunyikan semua bug','menghapus catatan','mengklaim selalu sempurna']],['Tujuan proyek yang jelas membantu …','menentukan pekerjaan yang perlu dilakukan',['menghapus kebutuhan rencana','menjamin tidak ada kendala','mengganti semua pengujian']]
],'business');
unit('heat','Suhu, kalor, dan perpindahan energi','Suhu berkaitan dengan keadaan termal benda, sedangkan kalor adalah energi yang berpindah karena perbedaan suhu. Konduksi terjadi melalui interaksi dalam bahan; konveksi melalui perpindahan fluida; radiasi melalui gelombang elektromagnetik.','Sendok logam yang ujungnya berada dalam air panas dapat menjadi hangat melalui konduksi. Panas Matahari mencapai Bumi melalui radiasi, tanpa memerlukan medium udara antarplanet.',[
 ['Kalor berpindah karena perbedaan …','suhu',['nama benda','warna label','jumlah huruf']],['Perpindahan panas pada sendok logam adalah …','konduksi',['konveksi saja','fotosintesis','rotasi']],['Panas Matahari sampai ke Bumi terutama melalui …','radiasi',['konduksi melalui ruang hampa','air mengalir','bunyi']],['Konveksi melibatkan …','perpindahan fluida',['hanya benda diam tanpa zat','semua perubahan kimia','perubahan nama unsur']]
],'science');
unit('waves','Gelombang, bunyi, dan cahaya','Gelombang membawa energi. Frekuensi adalah banyak getaran per sekon, satuannya hertz. Bunyi memerlukan medium, sedangkan cahaya dapat merambat dalam ruang hampa. Hubungan dasar gelombang adalah v = f × λ.','Jika frekuensi 2 Hz dan panjang gelombang 3 m, laju gelombang 6 m/s. Bunyi tidak merambat melalui ruang hampa karena tidak ada medium untuk membawa gangguan mekanisnya.',[
 ['Satuan frekuensi adalah …','hertz',['meter persegi','liter','kilogram']],['v = f × λ dengan f = 2 Hz dan λ = 3 m menghasilkan …','6 m/s',['5 m/s','1 m/s','9 m/s']],['Bunyi memerlukan …','medium',['ruang hampa saja','cahaya biru','muatan bank']],['Gelombang membawa …','energi',['semua medium berpindah permanen ke tujuan','nomor identitas','nama zat baru selalu']]
],'science');
unit('genetics','Pewarisan sifat dan variasi','DNA menyimpan informasi genetik. Gen adalah bagian DNA yang berperan dalam pembentukan produk fungsional. Sifat dipengaruhi gen dan lingkungan; tidak semua sifat mengikuti pola dominan-resesif sederhana. Variasi adalah bagian alami populasi.','Model persilangan Aa × Aa menghasilkan kemungkinan genotipe AA, Aa, Aa, dan aa. Dalam model dominansi penuh satu gen, proporsi fenotipe dapat 3:1. Ini model sederhana, bukan aturan semua sifat manusia.',[
 ['Informasi genetik disimpan dalam …','DNA',['air murni','lemak saja','udara']],['Pada model Aa × Aa, peluang aa adalah …','1/4',['1/2','3/4','1']],['Sifat organisme dipengaruhi …','gen dan lingkungan',['nama organisme saja','gen tanpa pengecualian','lingkungan tanpa peran gen']],['Pola dominan-resesif sederhana berlaku …','pada model tertentu',['untuk semua sifat manusia','untuk semua penyakit pasti','tanpa pengaruh konteks']]
],'science');
unit('mole','Mol dan persamaan reaksi','Mol adalah satuan jumlah zat. Persamaan reaksi disetarakan agar jumlah atom setiap unsur sama di kedua sisi. Koefisien reaksi menyatakan perbandingan jumlah partikel atau mol pada reaksi tersebut, bukan langsung perbandingan massa.','Pada 2H₂ + O₂ → 2H₂O, dua mol H₂ bereaksi dengan satu mol O₂ menghasilkan dua mol H₂O bila reaksi berlangsung sesuai model dan pereaksi mencukupi.',[
 ['Mol merupakan satuan …','jumlah zat',['suhu','arus','tekanan']],['Persamaan reaksi disetarakan untuk menjaga …','jumlah atom setiap unsur',['warna tulisan','panjang nama unsur','jumlah wadah']],['Perbandingan mol H₂ : O₂ pada contoh adalah …','2 : 1',['1 : 2','1 : 1','2 : 3']],['Koefisien reaksi tidak langsung menyatakan …','perbandingan massa',['perbandingan mol','perbandingan partikel','jumlah stoikiometris']]
],'science');
unit('acid','Asam, basa, dan indikator','Dalam konteks larutan berair pada kondisi umum, pH di bawah 7 bersifat asam dan di atas 7 bersifat basa. Skala pH bersifat logaritmik. Indikator membantu memperkirakan sifat larutan; pengukuran akurat memerlukan alat terkalibrasi.','Air murni sekitar 25°C memiliki pH mendekati 7. Jangan menilai keamanan zat hanya dari pH: konsentrasi, jenis zat, dan paparan juga penting. Jangan mencicipi larutan percobaan.',[
 ['Larutan dengan pH 3 bersifat …','asam',['basa','pasti netral','pasti aman diminum']],['Pada kondisi umum, pH 10 menunjukkan …','basa',['asam','netral tepat','gas murni']],['Skala pH bersifat …','logaritmik',['selalu linier','tanpa satuan waktu saja','acak']],['Keamanan zat ditentukan …','lebih dari sekadar pH',['hanya warna','hanya rasa','hanya angka 7']]
],'science');
unit('change','Perubahan sosial dan globalisasi','Perubahan sosial mencakup perubahan pola interaksi, nilai, dan lembaga dalam masyarakat. Teknologi dapat memperluas akses informasi sekaligus membawa tantangan. Nilai dampak dengan bukti dan sudut pandang beragam.','Perdagangan daring dapat membantu usaha menjangkau pelanggan, tetapi juga menuntut keterampilan digital dan perlindungan data. Dampaknya tidak sama bagi semua kelompok.',[
 ['Perubahan sosial dapat dipengaruhi oleh …','teknologi dan interaksi masyarakat',['warna kalender saja','satu nama orang saja','ukuran buku']],['Dampak teknologi pada semua orang …','dapat berbeda',['selalu sama persis','selalu tanpa masalah','selalu buruk']],['Menilai perubahan memerlukan …','bukti dan berbagai sudut pandang',['prasangka saja','satu unggahan tanpa sumber','jumlah huruf judul']],['Perdagangan daring membutuhkan perhatian pada …','perlindungan data',['membagikan OTP pelanggan','menghapus semua catatan','mengabaikan pesanan']]
],'map');
unit('trade','Perdagangan, kelangkaan, dan biaya peluang','Kelangkaan terjadi ketika sumber daya terbatas dibanding kebutuhan atau keinginan. Biaya peluang adalah nilai alternatif terbaik yang dilepas saat memilih. Perdagangan memungkinkan pertukaran, tetapi manfaat dan biaya perlu diperiksa.','Jika satu jam dipakai membuat poster, jam yang sama tidak dapat sekaligus dipakai menyelesaikan tugas lain. Alternatif terbaik yang dilepas menjadi pertimbangan biaya peluang.',[
 ['Biaya peluang adalah …','nilai alternatif terbaik yang dilepas',['semua uang yang pernah dimiliki','harga tertinggi di pasar selalu','semua alternatif dijumlahkan']],['Kelangkaan berkaitan dengan …','keterbatasan sumber daya',['semua barang gratis','kebutuhan selalu nol','persediaan tanpa batas']],['Satu sumber daya yang terbatas adalah …','waktu',['bilangan pada semua buku','nama bulan','huruf alfabet sebagai simbol']],['Keputusan ekonomi sebaiknya membandingkan …','manfaat dan biaya relevan',['iklan saja','tekanan teman saja','warna nota saja']]
],'map');
